#!/usr/bin/env python3\n\"\"\"\nDistance calculation utilities for GIS functionality.\nImplements Haversine formula for calculating distances between coordinates.\n\"\"\"\n\nimport math\nfrom typing import Tuple, Optional\n\ndef haversine_distance(lat1: float, lon1: float, lat2: float, lon2: float) -> float:\n    \"\"\"\n    Calculate the great circle distance between two points on Earth.\n    Uses the Haversine formula.\n    \n    Args:\n        lat1, lon1: Latitude and longitude of first point in decimal degrees\n        lat2, lon2: Latitude and longitude of second point in decimal degrees\n    \n    Returns:\n        Distance in kilometers\n    \"\"\"\n    # Convert decimal degrees to radians\n    lat1_rad = math.radians(lat1)\n    lon1_rad = math.radians(lon1)\n    lat2_rad = math.radians(lat2)\n    lon2_rad = math.radians(lon2)\n    \n    # Haversine formula\n    dlat = lat2_rad - lat1_rad\n    dlon = lon2_rad - lon1_rad\n    \n    a = (math.sin(dlat / 2) ** 2 + \n         math.cos(lat1_rad) * math.cos(lat2_rad) * math.sin(dlon / 2) ** 2)\n    \n    c = 2 * math.asin(math.sqrt(a))\n    \n    # Radius of Earth in kilometers\n    earth_radius_km = 6371.0\n    \n    # Calculate the distance\n    distance = earth_radius_km * c\n    \n    return distance\n\ndef format_distance(distance_km: float) -> str:\n    \"\"\"\n    Format distance for display.\n    \n    Args:\n        distance_km: Distance in kilometers\n    \n    Returns:\n        Formatted distance string\n    \"\"\"\n    if distance_km < 1.0:\n        # Show in meters for distances less than 1 km\n        meters = distance_km * 1000\n        return f\"{meters:.0f}m\"\n    elif distance_km < 10.0:\n        # Show one decimal place for distances less than 10 km\n        return f\"{distance_km:.1f}km\"\n    else:\n        # Show whole kilometers for longer distances\n        return f\"{distance_km:.0f}km\"\n\ndef calculate_project_supplier_distances(project_lat: float, project_lon: float, \n                                       suppliers: list) -> list:\n    \"\"\"\n    Calculate distances from a project to all suppliers.\n    \n    Args:\n        project_lat, project_lon: Project coordinates\n        suppliers: List of supplier objects with latitude/longitude\n    \n    Returns:\n        List of suppliers with added distance information, sorted by distance\n    \"\"\"\n    suppliers_with_distance = []\n    \n    for supplier in suppliers:\n        if supplier.latitude is not None and supplier.longitude is not None:\n            distance = haversine_distance(\n                project_lat, project_lon,\n                supplier.latitude, supplier.longitude\n            )\n            \n            # Create a copy of supplier data with distance\n            supplier_data = {\n                'id': supplier.id,\n                'name': supplier.name,\n                'contact_person': supplier.contact_person,\n                'phone': supplier.phone,\n                'address': supplier.address,\n                'latitude': supplier.latitude,\n                'longitude': supplier.longitude,\n                'distance_km': distance,\n                'distance_formatted': format_distance(distance)\n            }\n            suppliers_with_distance.append(supplier_data)\n    \n    # Sort by distance (nearest first)\n    suppliers_with_distance.sort(key=lambda x: x['distance_km'])\n    \n    return suppliers_with_distance\n\ndef find_nearest_suppliers(project_lat: float, project_lon: float, \n                          suppliers: list, limit: int = 5) -> list:\n    \"\"\"\n    Find the nearest suppliers to a project.\n    \n    Args:\n        project_lat, project_lon: Project coordinates\n        suppliers: List of supplier objects\n        limit: Maximum number of suppliers to return\n    \n    Returns:\n        List of nearest suppliers with distance information\n    \"\"\"\n    suppliers_with_distance = calculate_project_supplier_distances(\n        project_lat, project_lon, suppliers\n    )\n    \n    return suppliers_with_distance[:limit]\n\ndef calculate_distance_matrix(projects: list, suppliers: list) -> dict:\n    \"\"\"\n    Calculate distance matrix between all projects and suppliers.\n    \n    Args:\n        projects: List of project objects with coordinates\n        suppliers: List of supplier objects with coordinates\n    \n    Returns:\n        Dictionary with project IDs as keys and supplier distance lists as values\n    \"\"\"\n    distance_matrix = {}\n    \n    for project in projects:\n        if project.latitude is not None and project.longitude is not None:\n            suppliers_with_distance = calculate_project_supplier_distances(\n                project.latitude, project.longitude, suppliers\n            )\n            distance_matrix[project.id] = suppliers_with_distance\n    \n    return distance_matrix\n\n# Test function\nif __name__ == \"__main__\":\n    # Test the distance calculation\n    print(\"🧪 Testing Distance Calculator\")\n    print(\"=\" * 30)\n    \n    # Test coordinates (Mumbai to Delhi)\n    mumbai_lat, mumbai_lon = 19.0760, 72.8777\n    delhi_lat, delhi_lon = 28.7041, 77.1025\n    \n    distance = haversine_distance(mumbai_lat, mumbai_lon, delhi_lat, delhi_lon)\n    formatted = format_distance(distance)\n    \n    print(f\"Distance from Mumbai to Delhi: {distance:.2f} km\")\n    print(f\"Formatted: {formatted}\")\n    \n    # Test short distance (within Mumbai)\n    thane_lat, thane_lon = 19.2183, 72.9781\n    short_distance = haversine_distance(mumbai_lat, mumbai_lon, thane_lat, thane_lon)\n    short_formatted = format_distance(short_distance)\n    \n    print(f\"Distance from Mumbai to Thane: {short_distance:.2f} km\")\n    print(f\"Formatted: {short_formatted}\")\n    \n    print(\"✅ Distance calculator working correctly!\")\n